-- | Frozen owned native archives keep package-store discovery free of provider acquisition.
module Ecluse.Test.Contract.PackageStore.Cargo.Fixtures (
    packageText,
    packageName,
    primaryNative,
    siblingNative,
    storeRelease,
) where

import Data.Aeson (Value, encode, object, (.=))
import Data.ByteString qualified as BS
import Data.Map.Strict qualified as Map

import Ecluse.Core.Ecosystem (Ecosystem (Cargo))
import Ecluse.Core.Package (PackageName, mkPackageName)
import Ecluse.Test.Contract.PackageStore
import Ecluse.Test.Package (hexSha256Of)
import Ecluse.Test.Registry.Cargo.Fixtures

-- | Fixed package identity shared by the independent data and control planes.
packageText :: Text
packageText = "contract-package"

-- | Native Cargo names carry no namespace.
packageName :: PackageName
packageName = mkPackageName Cargo Nothing packageText

-- | Consumer fields and the complete archive expected from an accepted native upload.
storeRelease :: CargoRelease -> PackageStoreRelease
storeRelease release =
    PackageStoreRelease
        (crateVersion spec)
        (Map.fromList [("features", decodeUtf8 (toStrict (encode (crateFeatures spec)))), ("rust_version", "1.74")])
        (PackageStoreArtifact (crateName spec <> "-" <> crateVersion spec <> ".crate") (releaseArchive release) (releaseChecksum release) :| [])
  where
    spec = releaseCrate release

-- | An owned native archive with a manifest, README and library source.
primaryNative :: CargoRelease
primaryNative = nativeRelease "1.0.0" (object ["primary-feature" .= ([] :: [Text])]) "primary native fixture README\n" primaryBytes

-- | An owned native archive with a manifest, README and library source.
siblingNative :: CargoRelease
siblingNative = nativeRelease "2.0.0" (object ["sibling-feature" .= ([] :: [Text])]) "sibling native fixture README\n" siblingBytes

nativeRelease :: Text -> Value -> Text -> ByteString -> CargoRelease
nativeRelease version features readme bytes =
    let original = minimalCargoRelease packageText version
     in original
            { releaseCrate = (releaseCrate original){crateFeatures = features}
            , releaseArchive = bytes
            , releaseChecksum = hexSha256Of bytes
            , releaseReadme = readme
            }

